// Exercise 13.13. A good way to understand copy-control members and constructors is to define a simple class with these members in which each member prints its name: struct X { X() {std::cout <<...

#include <iostream>
#include <memory>
#include <vector>

struct X {
    X() { std::cout << "X() " << &*this << std::endl; }
    X(const X&) { std::cout << "X(const X&) " << &*this << std::endl; }
    X& operator=(const X &);
    ~X() {std::cout << "~X() " << &*this << std::endl; }
};

X&
X::operator=(const X &rhs)
{
    std::cout << "operator=(const X&) " << &*this << std::endl;
    return *this;
}

X func1(const X a)
{
    X w = a;
    return w;
}

X &func2(X &a)
{
    return a;
}

X *func3(X *a)
{
    return a;
}

int main()
{
    std::cout << "X a;\n";
    X a;
    std::cout << "\nX b;\n";
    X b;
    std::cout << "\na = b;\n";
    a = b;
    std::cout <<"\nX c(b);\n";
    X c(b);

