    std::vector<X> xvec1{a, b, c};

    std::cout << "\nxvec2 = vec1;\n";
    std::vector<X> xvec2(xvec1);

    // vector is reallocated
    std::cout << "\nxvec2.push_back(a);\n";
    xvec2.push_back(a);

    std::cout << "\nxvec2.pop_back();\n";
    xvec2.pop_back();

