        HasPtr(const std::string &s = std::string()) :
            ps(new std::string(s)), i(0) {}
        ~HasPtr() { delete ps; }
        HasPtr(const HasPtr& rhs) :
            ps(new std::string(*rhs.ps)), i(rhs.i) {}
