    using std::swap;
    swap(lhs.ps, rhs.ps);
    swap(lhs.i, rhs.i);
    std::cout << "swap(HasPtr &lhs, HasPtr &rhs)\n";
}

std::ostream& print(std::ostream &os, const HasPtr &p)
{
    os << p.ps << ' ' << *p.ps << ' ' << p.i;
    return os;
}

